body {
    font-family: Calibri, sans-serif;
}
h1 {
    background-color: #102a5c;
    box-shadow: 10px 10px 5px rgba(0,0,0,0.3);
    border-radius: 20px;
    color: #ffffff;
    font-size: 30px;
    font-family: Arial, sans-serif;
    text-align: center;
    font-weight: bold;
    margin-bottom: 15px;
    padding: 10px;
}
h2 {
    background-color: #102a5c;
    text-align: center;
    color: #ffffff;
    border-radius: 20px;
}
.arkusz-buttons {
    background-color: #1b3f8b;
    font-size: 20px;
}
.menu-buttons {
    margin-bottom: 20px;
    text-align: center;
}
.columns {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: flex-start;
    gap: 20px;
    margin-bottom: 20px;
}
.column {
    flex: 1 1 260px;
    max-width: 320px;
}
.column-buttons {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
}
.tests-buttons {
    margin-top: 10px;
}
.tests-buttons .arkusz-buttons {
    background-color: #214a9a;
}
.tests-buttons .arkusz-buttons:hover {
    background-color: #2f63bf;
}
button {
    padding: 10px 20px;
    font-size: 15px;
    margin: 5px;
    cursor: pointer;
    border: none;
    border-radius: 5px;
    background-color: #1b3f8b;
    color: white;

}
button:hover {
    background-color: #2f63bf;
}
.feedback {
    margin-top: 10px;
    font-weight: bold;
}
.correct {
    color: green;
}
.incorrect {
    color: red;
}
.quiz-section {

    text-align: left;
    border-top: 2px solid #d7deea;
    padding-top: 20px;
}
.zadanie {

    background-color: #f0f0f0;
    width: 75%;
    text-align: left;
    color: #000000;
    font-size: 14px;
    border-radius: 20px;
    margin: 20px auto;
    padding: 10px;
    box-shadow: 10px 10px 5px rgba(0,0,0,0.3);
}
.odp {
    background-color: #e6e6e6;
    text-align:left;
    margin: 20px auto;
    padding: 10px;
    color: #000000;
}
.zadanie-3-columns {
    display: flex;
    gap: 24px;
    flex-wrap: wrap;
    align-items: stretch;
    justify-content: center;
}
.zadanie-3-column {
    display: flex;
    flex-direction: column;
    justify-content: center;
    text-align: center;
}
.zadanie-3-middle {
    min-width: 90px;
}
.wynik{
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 12px;
}

.wynik p {
    margin: 0;
}

.answer-feedback {
    margin-left: 8px;
    font-weight: bold;
}
.button-row {
    display: flex;
    justify-content: center;
    gap: 8px;
    flex-wrap: wrap;
}
.lesson-video {
    display: block;
    width: 100%;
    max-width: 800px;
    height: auto;
    margin: 20px auto;
}

/* Style dla paska nawigacji */
.navbar {
    background-color: #102a5c;
    padding: 15px 0;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
    margin-bottom: 20px;
}

.navbar-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 20px;
}

.navbar-brand {
    font-size: 24px;
    font-weight: bold;
    color: #ffffff;
    text-decoration: none;
    font-family: Arial, sans-serif;
}

.navbar-menu {
    list-style: none;
    display: flex;
    gap: 25px;
    margin: 0;
    padding: 0;
}

.navbar-menu a {
    color: #ffffff;
    text-decoration: none;
    font-size: 16px;
    transition: color 0.3s ease;
}

.navbar-menu a:hover {
    color: #b0d4ff;
    text-decoration: underline;
}

@media (max-width: 600px) {
    .navbar-container {
        flex-direction: column;
        gap: 10px;
    }

    .navbar-menu {
        flex-direction: column;
        gap: 10px;
        text-align: center;
    }
}

